// Package auth authenticates applications (the callers of the
// tenant-pass API).
//
// Two methods are supported, alone or combined per application:
//
//   - Bearer token. tenant-pass stores only the SHA-256 of each token, so
//     the configuration file does not contain usable credentials. Tokens
//     are generated by `tenant-pass gen-app-token` (256 random bits), so
//     an unsalted fast hash is appropriate: there is nothing to brute
//     force.
//   - TLS client certificate, matched by a URI SAN (for example a SPIFFE
//     ID). Requires the server to be configured with a client CA.
//
// If an application has both configured, both must be presented.
package auth

import (
	"crypto/sha256"
	"crypto/subtle"
	"crypto/x509"
	"errors"
	"net/http"
	"strings"
)

// TokenPrefix marks tenant-pass application tokens, which makes them easy
// to find with secret scanners if they leak into a repository.
const TokenPrefix = "tpa_"

// maxTokenLength bounds the work done on an Authorization header.
const maxTokenLength = 256

// App is one configured application.
type App struct {
	Name string
	// TokenSHA256 is the SHA-256 of the application's bearer token, or
	// nil if the application authenticates by certificate only.
	TokenSHA256 []byte
	// ClientCertURI is the URI SAN the application's client certificate
	// must carry, or "" if no certificate is required.
	ClientCertURI string
}

// ErrUnauthenticated is returned for every authentication failure. The
// reason is not distinguished, to the caller or in the error value.
var ErrUnauthenticated = errors.New("auth: unauthenticated")

// Authenticator matches requests to applications.
type Authenticator struct {
	apps []App
}

// New validates apps and returns an Authenticator.
func New(apps []App) (*Authenticator, error) {
	tokens := map[string]bool{}
	uris := map[string]bool{}
	names := map[string]bool{}
	for _, a := range apps {
		if names[a.Name] {
			return nil, errors.New("auth: duplicate application name " + a.Name)
		}
		names[a.Name] = true
		if a.TokenSHA256 == nil && a.ClientCertURI == "" {
			return nil, errors.New("auth: application " + a.Name + " has no authentication method")
		}
		if a.TokenSHA256 != nil {
			if len(a.TokenSHA256) != sha256.Size {
				return nil, errors.New("auth: application " + a.Name + " has an invalid token hash")
			}
			if tokens[string(a.TokenSHA256)] {
				return nil, errors.New("auth: two applications share a token")
			}
			tokens[string(a.TokenSHA256)] = true
		}
		if a.ClientCertURI != "" {
			if uris[a.ClientCertURI] {
				return nil, errors.New("auth: two applications share a client certificate URI")
			}
			uris[a.ClientCertURI] = true
		}
	}
	return &Authenticator{apps: apps}, nil
}

// HashToken returns the SHA-256 of a token, as stored in configuration.
func HashToken(token string) []byte {
	sum := sha256.Sum256([]byte(token))
	return sum[:]
}

// bearer extracts the token from the Authorization header. It returns
// ("", true) when the header is absent and ("", false) when it is
// present but malformed.
func bearer(r *http.Request) (string, bool) {
	vals := r.Header.Values("Authorization")
	switch len(vals) {
	case 0:
		return "", true
	case 1:
	default:
		return "", false // multiple Authorization headers: ambiguous
	}
	scheme, tok, ok := strings.Cut(vals[0], " ")
	if !ok || !strings.EqualFold(scheme, "Bearer") || tok == "" || len(tok) > maxTokenLength {
		return "", false
	}
	return tok, true
}

// certURIs returns the URI SANs of the verified client certificate.
func certURIs(r *http.Request) []string {
	if r.TLS == nil || len(r.TLS.VerifiedChains) == 0 || len(r.TLS.VerifiedChains[0]) == 0 {
		return nil
	}
	leaf := r.TLS.VerifiedChains[0][0]
	return uriStrings(leaf)
}

func uriStrings(c *x509.Certificate) []string {
	out := make([]string, 0, len(c.URIs))
	for _, u := range c.URIs {
		out = append(out, u.String())
	}
	return out
}

// Authenticate returns the name of the application making the request.
func (a *Authenticator) Authenticate(r *http.Request) (string, error) {
	tok, ok := bearer(r)
	if !ok {
		return "", ErrUnauthenticated
	}
	uris := certURIs(r)

	var match *App
	if tok != "" {
		// Compare against every configured hash without stopping early,
		// so response time does not depend on which (if any) app
		// matched. The hash of a 256-bit token leaks nothing useful
		// anyway; this is defence in depth.
		h := HashToken(tok)
		for i := range a.apps {
			if a.apps[i].TokenSHA256 != nil && subtle.ConstantTimeCompare(h, a.apps[i].TokenSHA256) == 1 {
				match = &a.apps[i]
			}
		}
		if match == nil {
			return "", ErrUnauthenticated
		}
	} else {
		// Certificate-only applications. A certificate whose URI SANs
		// name more than one application is ambiguous and refused,
		// rather than silently becoming whichever is configured first.
		for i := range a.apps {
			if a.apps[i].TokenSHA256 == nil && containsString(uris, a.apps[i].ClientCertURI) {
				if match != nil {
					return "", ErrUnauthenticated
				}
				match = &a.apps[i]
			}
		}
		if match == nil {
			return "", ErrUnauthenticated
		}
	}
	if match.ClientCertURI != "" && !containsString(uris, match.ClientCertURI) {
		return "", ErrUnauthenticated
	}
	return match.Name, nil
}

func containsString(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}
